import React, { useEffect, useRef, useState, useContext, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../../../Context/AuthContext";
import "./ModalLogin.css";

const ModalLogin = ({ show, handleClose }) => {
    const { login } = useContext(AuthContext);
    const navigate = useNavigate();

    const [form, setForm] = useState({
        accountname: localStorage.getItem("remember_accountname") || "",
        password: "",
        remember: !!localStorage.getItem("remember_accountname"),
    });
    const [showPassword, setShowPassword] = useState(false);
    const [submitting, setSubmitting] = useState(false);
    const [errMsg, setErrMsg] = useState("");

    const dialogRef = useRef(null);
    const firstFieldRef = useRef(null);

    // Mount/unmount side-effects
    useEffect(() => {
        if (!show) return;

        // Lock scroll behind modal
        const prevOverflow = document.body.style.overflow;
        document.body.style.overflow = "hidden";

        // Focus first input
        firstFieldRef.current?.focus();

        // Close on ESC
        const onKey = (e) => {
            if (e.key === "Escape") handleClose();
            // Simple focus trap: keep tab inside dialog
            if (e.key === "Tab" && dialogRef.current) {
                const focusables = dialogRef.current.querySelectorAll(
                    'a[href],button:not([disabled]),textarea,input,select,[tabindex]:not([tabindex="-1"])'
                );
                const first = focusables[0];
                const last = focusables[focusables.length - 1];
                if (e.shiftKey && document.activeElement === first) {
                    e.preventDefault();
                    last.focus();
                } else if (!e.shiftKey && document.activeElement === last) {
                    e.preventDefault();
                    first.focus();
                }
            }
        };
        document.addEventListener("keydown", onKey);

        return () => {
            document.body.style.overflow = prevOverflow;
            document.removeEventListener("keydown", onKey);
        };
    }, [show, handleClose]);

    const onBackdropClick = (e) => {
        if (e.target === e.currentTarget) handleClose();
    };

    const onChange = (e) => {
        const { name, value, type, checked } = e.target;
        setForm((s) => ({ ...s, [name]: type === "checkbox" ? checked : value }));
        setErrMsg("");
    };

    const rememberAccountname = useCallback((remember, accountname) => {
        if (remember && accountname) {
            localStorage.setItem("remember_accountname", accountname);
        } else {
            localStorage.removeItem("remember_accountname");
        }
    }, []);

    const handleRegisterClick = () => {
        handleClose();
        navigate("/register");
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setErrMsg("");

        if (!form.accountname?.trim() || !form.password) {
            setErrMsg("Vui lòng nhập đầy đủ thông tin.");
            return;
        }

        setSubmitting(true);
        try {
            await login({ accountname: form.accountname.trim(), password: form.password });
            rememberAccountname(form.remember, form.accountname.trim());
            setForm((s) => ({ ...s, password: "" }));
            handleClose();
            navigate("/");
        } catch (error) {
            const msg = error?.response?.data?.message || error?.message || "Đăng nhập thất bại.";
            setErrMsg(msg);
        } finally {
            setSubmitting(false);
        }
    };

    if (!show) return null;

    return (
        <div
            className="modal-backdrop-custom"
            aria-hidden={!show}
            onClick={onBackdropClick}
        >
            <div
                className="modal-dialog modal-lg modal-dialog-centered"
                role="dialog"
                aria-modal="true"
                aria-labelledby="loginTitle"
                aria-describedby="loginDesc"
                ref={dialogRef}
            >
                <div className="modal-content custom-modal">
                    <div className="modal-body p-0">
                        <div className="row g-0">
                            {/* Left side */}
                            <div className="col-md-5 modal-left-gradient d-flex flex-column justify-content-center align-items-center p-5 text-white">
                                <div className="text-center">
                                    <h2 className="fw-bold mb-3 display-6" id="loginTitle">ĐĂNG KÝ</h2>
                                    <p className="mb-4 fs-6" id="loginDesc">Bạn chưa có tài khoản, đăng ký ngay!</p>
                                    <button
                                        type="button"
                                        className="btn btn-outline-light btn-lg px-4 py-2 rounded-3 fw-semibold border-2"
                                        onClick={handleRegisterClick}
                                    >
                                        ĐĂNG KÝ TÀI KHOẢN MỚI
                                    </button>
                                </div>
                            </div>

                            {/* Right side */}
                            <div className="col-md-8   modal-right">
                                <button
                                    type="button"
                                    className="btn-close position-absolute top-0 end-0 m-3"
                                    onClick={handleClose}
                                    aria-label="Đóng"
                                />
                                <div className="login-form-container">
                                    <h3 className="fw-bold mb-4 text-dark">ĐĂNG NHẬP</h3>

                                    {errMsg && (
                                        <div className="alert alert-danger py-2" role="alert">
                                            {errMsg}
                                        </div>
                                    )}

                                    <form onSubmit={handleSubmit} noValidate>
                                        {/* Accountname */}
                                        <div className="mb-3">
                                            <label className="form-label fw-semibold text-dark mb-2" htmlFor="accountname">
                                                Tên tài khoản *
                                            </label>
                                            <input
                                                id="accountname"
                                                name="accountname"
                                                type="text"
                                                className="form-control form-control-lg bg-light border-0 rounded-3 px-3 shadow-none input-focus"
                                                placeholder="Nhập tên tài khoản"
                                                autoComplete="username"
                                                value={form.accountname}
                                                onChange={onChange}
                                                ref={firstFieldRef}
                                                required
                                            />
                                        </div>

                                        {/* Password */}
                                        <div className="mb-3">
                                            <label className="form-label fw-semibold text-dark mb-2" htmlFor="password">
                                                Mật khẩu *
                                            </label>
                                            <div className="position-relative">
                                                <input
                                                    id="password"
                                                    name="password"
                                                    type={showPassword ? "text" : "password"}
                                                    className="form-control form-control-lg bg-light border-0 rounded-3 px-3 pe-5 shadow-none input-focus"
                                                    placeholder="••••••••"
                                                    autoComplete="current-password"
                                                    value={form.password}
                                                    onChange={onChange}
                                                    required
                                                />
                                                <button
                                                    type="button"
                                                    className="btn btn-sm btn-link password-toggle"
                                                    aria-label={showPassword ? "Ẩn mật khẩu" : "Hiện mật khẩu"}
                                                    onClick={() => setShowPassword((s) => !s)}
                                                    tabIndex={0}
                                                >
                                                    {/* Eye icon (inline SVG để tránh phụ thuộc font icon) */}
                                                    {showPassword ? (
                                                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none">
                                                            <path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z" stroke="currentColor" strokeWidth="2" />
                                                            <path d="M14.12 9.88a3 3 0 1 1-4.24 4.24" stroke="currentColor" strokeWidth="2" />
                                                            <path d="M3 3l18 18" stroke="currentColor" strokeWidth="2" />
                                                        </svg>
                                                    ) : (
                                                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none">
                                                            <path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z" stroke="currentColor" strokeWidth="2" />
                                                            <circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" />
                                                        </svg>
                                                    )}
                                                </button>
                                            </div>
                                        </div>

                                        {/* Remember */}
                                        <div className="form-check mb-3">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                id="remember"
                                                name="remember"
                                                checked={form.remember}
                                                onChange={onChange}
                                            />
                                            <label className="form-check-label text-dark" htmlFor="remember">
                                                Ghi nhớ tài khoản
                                            </label>
                                        </div>

                                        {/* Submit */}
                                        <button
                                            type="submit"
                                            className="btn btn-brand btn-lg w-100 fw-bold rounded-3 mb-3"
                                            disabled={submitting}
                                        >
                                            {submitting ? "ĐANG ĐĂNG NHẬP..." : "ĐĂNG NHẬP"}
                                        </button>

                                        {/* Forgot */}
                                        <div className="text-center mb-4">
                                            <a href="/forgot-password" className="link-muted">
                                                Quên mật khẩu?
                                            </a>
                                        </div>
                                    </form>

                                    {/* Social */}
                                    <div className="social-row">
                                        <button type="button" className="btn social-btn fb" aria-label="Đăng nhập bằng Facebook">
                                            <span className="social-icon">f</span> Facebook
                                        </button>
                                        <button type="button" className="btn social-btn gg" aria-label="Đăng nhập bằng Google">
                                            <span className="social-icon">G</span> Google
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>{/* row */}
                    </div>{/* body */}
                </div>
            </div>
        </div>
    );
};

export default ModalLogin;
